window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["airbnb"]={html:"<div class=\"own-airbnb\">\n  <header class=\"ab-nav\">\n    <a class=\"ab-brand\" href=\"#ab-top\" aria-label=\"Northwind home\">\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 2c2.2 0 4 1.8 4 4 0 3-2.4 5.8-3.4 9.9L12 18l-.6-2.1C10.4 11.8 8 9 8 6c0-2.2 1.8-4 4-4Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><circle cx=\"12\" cy=\"6.2\" r=\"1.5\" fill=\"currentColor\"/></svg>\n      <span>Northwind</span>\n    </a>\n    <nav class=\"ab-tabs\" aria-label=\"Products\">\n      <a href=\"#ab-cards\" class=\"ab-tab on\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 11 12 4l8 7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M6 10v9h12v-9\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg>Dashboards</a>\n      <a href=\"#ab-regions\" class=\"ab-tab\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M4 12h16M12 4c2.5 3 2.5 13 0 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg>Regions<span class=\"ab-new\">New</span></a>\n      <a href=\"#ab-plan\" class=\"ab-tab\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 18V9m5 9V5m5 13v-7m5 7V7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg>Forecast<span class=\"ab-new\">New</span></a>\n    </nav>\n    <div class=\"ab-utils\">\n      <a class=\"ab-util\" href=\"#\">Host a board</a>\n      <button class=\"ab-globe\" type=\"button\" aria-label=\"Language\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M4 12h16M12 4c2.5 3 2.5 13 0 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></button>\n      <button class=\"ab-account\" type=\"button\" aria-label=\"Account menu\"><span class=\"ab-account-lines\"><i></i><i></i><i></i></span><span class=\"ab-avatar\">FL</span></button>\n    </div>\n  </header>\n\n  <main id=\"ab-top\">\n    <section class=\"ab-hero\" aria-labelledby=\"ab-h1\">\n      <h1 id=\"ab-h1\" class=\"ab-h1\">Inspiration for sharper operations</h1>\n      <form class=\"ab-search\" role=\"search\" onsubmit=\"return false\">\n        <div class=\"ab-seg\"><span class=\"ab-seg-label\">Region</span><span class=\"ab-seg-value\">All regions</span></div>\n        <span class=\"ab-seg-div\" aria-hidden=\"true\"></span>\n        <div class=\"ab-seg\"><span class=\"ab-seg-label\">Period</span><span class=\"ab-seg-value\">This quarter</span></div>\n        <span class=\"ab-seg-div\" aria-hidden=\"true\"></span>\n        <div class=\"ab-seg ab-seg-wide\"><span class=\"ab-seg-label\">Metric</span><span class=\"ab-seg-value ab-seg-muted\">Throughput, yield, cost…</span></div>\n        <button class=\"ab-orb\" type=\"submit\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"/><path d=\"m20 20-4.2-4.2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\"/></svg></button>\n      </form>\n    </section>\n\n    <section id=\"ab-regions\" class=\"ab-band\" aria-labelledby=\"ab-regions-h\">\n      <h2 id=\"ab-regions-h\" class=\"ab-h2\">Explore by region</h2>\n      <div class=\"ab-city-grid\">\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Luzon</span><span class=\"ab-city-sub\">Manufacturing</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Visayas</span><span class=\"ab-city-sub\">Logistics</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Mindanao</span><span class=\"ab-city-sub\">Agri ops</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Singapore</span><span class=\"ab-city-sub\">Distribution</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Sydney</span><span class=\"ab-city-sub\">Fulfilment</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Auckland</span><span class=\"ab-city-sub\">Support</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Osaka</span><span class=\"ab-city-sub\">Assembly</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Busan</span><span class=\"ab-city-sub\">Port ops</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Jakarta</span><span class=\"ab-city-sub\">Sourcing</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Mumbai</span><span class=\"ab-city-sub\">Analytics</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Dubai</span><span class=\"ab-city-sub\">Trade desk</span></a>\n        <a class=\"ab-city\" href=\"#\"><span class=\"ab-city-name\">Rotterdam</span><span class=\"ab-city-sub\">Recycling</span></a>\n      </div>\n    </section>\n\n    <section id=\"ab-cards\" class=\"ab-band\" aria-labelledby=\"ab-cards-h\">\n      <div class=\"ab-band-head\">\n        <h2 id=\"ab-cards-h\" class=\"ab-h2\">Boards our teams keep open</h2>\n        <a class=\"ab-link\" href=\"#\">Show all 48 boards</a>\n      </div>\n      <div class=\"ab-card-grid\" id=\"abCardGrid\"></div>\n    </section>\n\n    <section class=\"ab-split\" aria-labelledby=\"ab-split-h\">\n      <div class=\"ab-split-body\">\n        <h2 id=\"ab-split-h\" class=\"ab-h2\">Built for the whole floor</h2>\n        <p class=\"ab-lead\">Every board carries the same numbers the night shift sees. Region splits, line yield, and cost per unit resolve against one governed model — no exports, no stale mirrors.</p>\n        <ul class=\"ab-amenities\">\n          <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 7 10 17l-6-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><span><b>Live throughput rows</b><em>Refreshed every fifteen minutes across regions.</em></span></li>\n          <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 7 10 17l-6-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><span><b>Yield guardrails</b><em>Flags a line the moment it drifts below grade.</em></span></li>\n          <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 7 10 17l-6-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><span><b>One shared export</b><em>CSV, PDF, or a scheduled digest to your inbox.</em></span></li>\n        </ul>\n      </div>\n      <aside class=\"ab-reserve\" aria-label=\"Plan summary\">\n        <span class=\"ab-reserve-price\">$4,900 <small>/ month</small></span>\n        <span class=\"ab-reserve-meta\">Operations tier · up to 40 seats</span>\n        <div class=\"ab-reserve-row ab-reserve-dates\">\n          <span><em>Start</em><b>Today</b></span>\n          <span><em>Renews</em><b>Monthly</b></span>\n        </div>\n        <div class=\"ab-reserve-guests\">\n          <span>Regions</span>\n          <span class=\"ab-stepper\"><button type=\"button\" aria-label=\"Fewer regions\">−</button><b>12</b><button type=\"button\" aria-label=\"More regions\">+</button></span>\n        </div>\n        <button class=\"ab-btn ab-btn-primary ab-btn-block\" type=\"button\">Start free trial</button>\n        <dl class=\"ab-fees\">\n          <div><dt>Data seats</dt><dd>$4,900</dd></div>\n          <div><dt>Extra region</dt><dd>$180</dd></div>\n          <div class=\"ab-fees-total\"><dt>Billed monthly</dt><dd>$4,900</dd></div>\n        </dl>\n        <p class=\"ab-reserve-note\">No card required for the first 30 days.</p>\n      </aside>\n    </section>\n\n    <section class=\"ab-band\" aria-labelledby=\"ab-reviews-h\">\n      <h2 id=\"ab-reviews-h\" class=\"ab-h2\">What operators say</h2>\n      <div class=\"ab-reviews\">\n        <article class=\"ab-review\">\n          <div class=\"ab-review-head\"><span class=\"ab-review-av\">RS</span><span><b>Rhea Santos</b><em>Plant lead · Visayas</em></span></div>\n          <p>We cut the morning stand-up from an hour to twelve minutes. The yield row is the single number everyone trusts now.</p>\n          <a class=\"ab-link\" href=\"#\">Show more</a>\n        </article>\n        <article class=\"ab-review\">\n          <div class=\"ab-review-head\"><span class=\"ab-review-av\">DO</span><span><b>Dane Ocampo</b><em>Ops manager · Luzon</em></span></div>\n          <p>The region board caught a drift two shifts before it would have hit a customer. That paid for the year on its own.</p>\n          <a class=\"ab-link\" href=\"#\">Show more</a>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"ab-cta\" aria-labelledby=\"ab-cta-h\">\n      <div class=\"ab-cta-copy\">\n        <p class=\"ab-cta-kicker\">Northwind for operations</p>\n        <h2 id=\"ab-cta-h\" class=\"ab-cta-h\">Bring every region onto one board</h2>\n      </div>\n      <a class=\"ab-btn ab-btn-primary\" href=\"#\">Get started</a>\n    </section>\n  </main>\n\n  <footer class=\"ab-footer\">\n    <div class=\"ab-foot-cols\">\n      <div class=\"ab-foot-col\"><h3>Support</h3><a href=\"#\">Help centre</a><a href=\"#\">Status</a><a href=\"#\">Contact ops desk</a></div>\n      <div class=\"ab-foot-col\"><h3>Hosting</h3><a href=\"#\">Share a board</a><a href=\"#\">Coverage map</a><a href=\"#\">Resource library</a></div>\n      <div class=\"ab-foot-col\"><h3>Northwind</h3><a href=\"#\">Newsroom</a><a href=\"#\">Careers</a><a href=\"#\">Investors</a></div>\n    </div>\n    <div class=\"ab-legal\">\n      <span>© 2026 Northwind Analytics — sample data, showcase only</span>\n      <span class=\"ab-legal-right\">\n        <button class=\"ab-legal-btn\" type=\"button\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M4 12h16M12 4c2.5 3 2.5 13 0 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg>English (US)</button>\n        <button class=\"ab-legal-btn\" type=\"button\">USD</button>\n        <a class=\"ab-social\" href=\"#\" aria-label=\"Community\">f</a>\n        <a class=\"ab-social\" href=\"#\" aria-label=\"Updates\">X</a>\n      </span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Airbnb design language, for showcase.html ══════════\n   White canvas, one Rausch voltage, pill search bar, photo-first property cards,\n   modest Cereal-weight type (Inter substitute), soft radii, one shadow tier. */\n\n.own-airbnb {\n  --primary: #ff385c;\n  --primary-active: #e00b41;\n  --primary-disabled: #ffd1da;\n  --ink: #222222;\n  --body: #3f3f3f;\n  --muted: #6a6a6a;\n  --muted-soft: #929292;\n  --hairline: #dddddd;\n  --hairline-soft: #ebebeb;\n  --canvas: #ffffff;\n  --surface-soft: #f7f7f7;\n  --surface-strong: #f2f2f2;\n  --scrim: #000000;\n  --r-xs: 4px;\n  --r-sm: 8px;\n  --r-md: 14px;\n  --r-lg: 20px;\n  --r-xl: 32px;\n  --r-full: 9999px;\n  --shadow: rgba(0, 0, 0, .02) 0 0 0 1px, rgba(0, 0, 0, .04) 0 2px 6px 0, rgba(0, 0, 0, .1) 0 4px 8px 0;\n  --font: 'Inter', 'Airbnb Cereal VF', Circular, -apple-system, system-ui, Roboto, 'Helvetica Neue', sans-serif;\n  --gut: clamp(24px, 5cqi, 80px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n}\n.own-airbnb *, .own-airbnb *::before, .own-airbnb *::after { box-sizing: border-box; }\n.own-airbnb a { color: inherit; text-decoration: none; }\n.own-airbnb button { font: inherit; cursor: pointer; }\n.own-airbnb :focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }\n\n/* ── top nav (80px, hairline) ─────────────────────────────────────────────── */\n.own-airbnb .ab-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 20px;\n  height: 80px; padding: 0 var(--gut);\n  background: var(--canvas); border-bottom: 1px solid var(--hairline);\n}\n.own-airbnb .ab-brand { display: flex; align-items: center; gap: 7px; color: var(--primary); font-weight: 700; font-size: 20px; letter-spacing: -.02em; }\n.own-airbnb .ab-brand svg { width: 26px; height: 26px; }\n.own-airbnb .ab-tabs { display: flex; align-items: center; gap: 4px; margin: 0 auto; }\n.own-airbnb .ab-tab { display: inline-flex; align-items: center; gap: 8px; position: relative; padding: 10px 14px; border-radius: var(--r-full); font-size: 16px; font-weight: 600; color: var(--muted); }\n.own-airbnb .ab-tab svg { width: 22px; height: 22px; }\n.own-airbnb .ab-tab:hover { background: var(--surface-soft); color: var(--ink); }\n.own-airbnb .ab-tab.on { color: var(--ink); }\n.own-airbnb .ab-tab.on::after { content: ''; position: absolute; left: 14px; right: 14px; bottom: 0; height: 2px; background: var(--ink); border-radius: 2px; }\n.own-airbnb .ab-new { font-size: 8px; font-weight: 700; letter-spacing: .32px; text-transform: uppercase; padding: 2px 6px; border-radius: var(--r-full); background: var(--ink); color: #fff; }\n.own-airbnb .ab-utils { display: flex; align-items: center; gap: 6px; margin-left: auto; }\n.own-airbnb .ab-util { padding: 10px 14px; border-radius: var(--r-full); font-size: 14px; font-weight: 600; }\n.own-airbnb .ab-util:hover { background: var(--surface-soft); }\n.own-airbnb .ab-globe { display: grid; place-items: center; width: 40px; height: 40px; border: 0; border-radius: var(--r-full); background: transparent; }\n.own-airbnb .ab-globe:hover { background: var(--surface-soft); }\n.own-airbnb .ab-globe svg { width: 18px; height: 18px; }\n.own-airbnb .ab-account { display: flex; align-items: center; gap: 8px; padding: 5px 5px 5px 12px; border: 1px solid var(--hairline); border-radius: var(--r-full); background: var(--canvas); }\n.own-airbnb .ab-account:hover { box-shadow: var(--shadow); }\n.own-airbnb .ab-account-lines { display: grid; gap: 3px; }\n.own-airbnb .ab-account-lines i { display: block; width: 14px; height: 2px; background: var(--ink); border-radius: 2px; }\n.own-airbnb .ab-avatar { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--ink); color: #fff; font-size: 11px; font-weight: 700; }\n\n/* ── hero ─────────────────────────────────────────────────────────────────── */\n.own-airbnb .ab-hero { max-width: 1280px; margin: 0 auto; padding: 56px var(--gut) 8px; }\n.own-airbnb .ab-h1 { font-size: 28px; font-weight: 700; line-height: 1.43; letter-spacing: 0; margin-bottom: 24px; }\n.own-airbnb .ab-search {\n  display: flex; align-items: center; gap: 2px;\n  background: var(--canvas); border: 1px solid var(--hairline); border-radius: var(--r-full);\n  padding: 6px 6px 6px 8px; box-shadow: var(--shadow); max-width: 860px;\n}\n.own-airbnb .ab-seg { display: grid; gap: 1px; padding: 8px 24px; border-radius: var(--r-full); cursor: pointer; min-width: 0; }\n.own-airbnb .ab-seg:hover { background: var(--surface-soft); }\n.own-airbnb .ab-seg-wide { flex: 1; }\n.own-airbnb .ab-seg-label { font-size: 14px; font-weight: 500; color: var(--ink); }\n.own-airbnb .ab-seg-value { font-size: 14px; font-weight: 400; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.own-airbnb .ab-seg-muted { color: var(--muted-soft); }\n.own-airbnb .ab-seg-div { width: 1px; height: 32px; background: var(--hairline); flex: none; }\n.own-airbnb .ab-orb { display: grid; place-items: center; width: 48px; height: 48px; flex: none; margin-left: auto; border: 0; border-radius: 50%; background: var(--primary); color: #fff; }\n.own-airbnb .ab-orb:hover { background: var(--primary-active); }\n.own-airbnb .ab-orb svg { width: 20px; height: 20px; }\n\n/* ── generic band ─────────────────────────────────────────────────────────── */\n.own-airbnb .ab-band { max-width: 1280px; margin: 0 auto; padding: 64px var(--gut) 0; }\n.own-airbnb .ab-h2 { font-size: 22px; font-weight: 500; line-height: 1.18; letter-spacing: -.44px; }\n.own-airbnb .ab-band-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 20px; }\n.own-airbnb .ab-link { font-size: 14px; font-weight: 500; color: var(--ink); text-decoration: underline; text-underline-offset: 3px; }\n.own-airbnb .ab-link:hover { color: var(--primary); }\n\n/* ── city grid ────────────────────────────────────────────────────────────── */\n.own-airbnb .ab-city-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; margin-top: 20px; }\n.own-airbnb .ab-city { display: grid; gap: 2px; padding: 12px 14px; border-radius: var(--r-md); border: 1px solid var(--hairline-soft); transition: box-shadow .15s, border-color .15s; }\n.own-airbnb .ab-city:hover { box-shadow: var(--shadow); border-color: transparent; }\n.own-airbnb .ab-city-name { font-size: 16px; font-weight: 600; }\n.own-airbnb .ab-city-sub { font-size: 14px; color: var(--muted); }\n\n/* ── property cards (photo-first) ─────────────────────────────────────────── */\n.own-airbnb .ab-card-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px 16px; }\n.own-airbnb .ab-card { display: grid; gap: 10px; text-align: left; }\n.own-airbnb .ab-card-photo {\n  position: relative; aspect-ratio: 1 / 1; border-radius: var(--r-md); overflow: hidden;\n  background: var(--ph, var(--surface-strong));\n}\n.own-airbnb .ab-card-photo::before { content: ''; position: absolute; inset: 0; background: var(--ph, linear-gradient(140deg, #f2f2f2, #ddd)); transition: transform .4s ease; }\n.own-airbnb .ab-card:hover .ab-card-photo::before { transform: scale(1.05); }\n.own-airbnb .ab-card-photo::after { content: ''; position: absolute; inset: 0; background: var(--ov, transparent); }\n.own-airbnb .ab-fav { position: absolute; top: 12px; left: 12px; z-index: 2; padding: 4px 10px; border-radius: var(--r-full); background: var(--canvas); color: var(--ink); font-size: 11px; font-weight: 600; box-shadow: var(--shadow); }\n.own-airbnb .ab-heart { position: absolute; top: 10px; right: 10px; z-index: 2; display: grid; place-items: center; width: 32px; height: 32px; border: 0; border-radius: 50%; background: rgba(255, 255, 255, .8); }\n.own-airbnb .ab-heart svg { width: 18px; height: 18px; fill: rgba(0, 0, 0, .35); stroke: #fff; stroke-width: 1.6; }\n.own-airbnb .ab-heart.on svg { fill: var(--primary); stroke: #fff; }\n.own-airbnb .ab-card-title { font-size: 16px; font-weight: 600; line-height: 1.25; }\n.own-airbnb .ab-card-meta { font-size: 14px; color: var(--muted); line-height: 1.43; margin-top: -6px; }\n.own-airbnb .ab-card-foot { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-top: -4px; }\n.own-airbnb .ab-card-price { font-size: 14px; font-weight: 600; }\n.own-airbnb .ab-card-price small { font-weight: 400; color: var(--muted); }\n.own-airbnb .ab-card-rating { display: inline-flex; align-items: center; gap: 4px; font-size: 14px; font-weight: 500; }\n.own-airbnb .ab-card-rating svg { width: 13px; height: 13px; fill: var(--ink); }\n\n/* ── split / reservation ──────────────────────────────────────────────────── */\n.own-airbnb .ab-split { max-width: 1080px; margin: 0 auto; padding: 64px var(--gut) 0; display: grid; grid-template-columns: 1.6fr 1fr; gap: 40px; align-items: start; }\n.own-airbnb .ab-lead { margin: 14px 0 20px; font-size: 16px; color: var(--body); max-width: 54ch; }\n.own-airbnb .ab-amenities { list-style: none; display: grid; gap: 18px; }\n.own-airbnb .ab-amenities li { display: grid; grid-template-columns: 24px 1fr; gap: 14px; padding: 12px 0; border-top: 1px solid var(--hairline-soft); }\n.own-airbnb .ab-amenities li:last-child { border-bottom: 1px solid var(--hairline-soft); }\n.own-airbnb .ab-amenities svg { width: 22px; height: 22px; color: var(--primary); }\n.own-airbnb .ab-amenities b { display: block; font-size: 16px; font-weight: 600; }\n.own-airbnb .ab-amenities em { font-style: normal; font-size: 14px; color: var(--muted); }\n.own-airbnb .ab-reserve { position: sticky; top: 168px; border: 1px solid var(--hairline); border-radius: var(--r-md); padding: 24px; box-shadow: var(--shadow); background: var(--canvas); display: grid; gap: 16px; }\n.own-airbnb .ab-reserve-price { font-size: 21px; font-weight: 700; }\n.own-airbnb .ab-reserve-price small { font-size: 14px; font-weight: 400; color: var(--muted); }\n.own-airbnb .ab-reserve-meta { font-size: 14px; color: var(--muted); margin-top: -10px; }\n.own-airbnb .ab-reserve-row { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--hairline); border-radius: var(--r-sm); overflow: hidden; }\n.own-airbnb .ab-reserve-row span { display: grid; gap: 2px; padding: 10px 14px; }\n.own-airbnb .ab-reserve-row span + span { border-left: 1px solid var(--hairline); }\n.own-airbnb .ab-reserve-row em { font-style: normal; font-size: 12px; font-weight: 700; letter-spacing: .02em; }\n.own-airbnb .ab-reserve-row b { font-size: 14px; font-weight: 400; color: var(--muted); }\n.own-airbnb .ab-reserve-guests { display: flex; align-items: center; justify-content: space-between; border: 1px solid var(--hairline); border-radius: var(--r-sm); padding: 12px 14px; font-size: 14px; font-weight: 500; }\n.own-airbnb .ab-stepper { display: inline-flex; align-items: center; gap: 12px; }\n.own-airbnb .ab-stepper button { display: grid; place-items: center; width: 28px; height: 28px; border: 1px solid var(--hairline); border-radius: 50%; background: var(--canvas); font-size: 16px; line-height: 1; }\n.own-airbnb .ab-stepper button:hover { border-color: var(--ink); }\n.own-airbnb .ab-btn { display: inline-flex; align-items: center; justify-content: center; height: 48px; padding: 0 24px; border: 1px solid transparent; border-radius: var(--r-sm); font-size: 16px; font-weight: 500; }\n.own-airbnb .ab-btn-primary { background: var(--primary); color: #fff; }\n.own-airbnb .ab-btn-primary:hover { background: var(--primary-active); }\n.own-airbnb .ab-btn-block { width: 100%; }\n.own-airbnb .ab-fees { display: grid; gap: 10px; font-size: 14px; }\n.own-airbnb .ab-fees div { display: flex; justify-content: space-between; color: var(--body); }\n.own-airbnb .ab-fees-total { border-top: 1px solid var(--hairline); padding-top: 12px; font-weight: 600; color: var(--ink); }\n.own-airbnb .ab-reserve-note { font-size: 13px; color: var(--muted); text-align: center; }\n\n/* ── reviews ──────────────────────────────────────────────────────────────── */\n.own-airbnb .ab-reviews { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 20px; }\n.own-airbnb .ab-review { display: grid; gap: 12px; padding: 24px; border: 1px solid var(--hairline-soft); border-radius: var(--r-md); }\n.own-airbnb .ab-review-head { display: flex; align-items: center; gap: 12px; }\n.own-airbnb .ab-review-av { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 50%; background: var(--surface-strong); font-weight: 700; font-size: 14px; }\n.own-airbnb .ab-review-head b { display: block; font-size: 16px; font-weight: 600; }\n.own-airbnb .ab-review-head em { font-style: normal; font-size: 14px; color: var(--muted); }\n.own-airbnb .ab-review p { font-size: 14px; color: var(--body); line-height: 1.43; margin: 0; }\n\n/* ── CTA ──────────────────────────────────────────────────────────────────── */\n.own-airbnb .ab-cta { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; margin: 64px var(--gut) 0; padding: 40px 48px; border-radius: var(--r-lg); background: var(--surface-soft); }\n.own-airbnb .ab-cta-kicker { font-size: 14px; font-weight: 600; color: var(--primary); margin-bottom: 6px; }\n.own-airbnb .ab-cta-h { font-size: 22px; font-weight: 500; letter-spacing: -.44px; }\n\n/* ── footer ───────────────────────────────────────────────────────────────── */\n.own-airbnb .ab-footer { margin-top: 64px; border-top: 1px solid var(--hairline); padding: 48px var(--gut) 32px; }\n.own-airbnb .ab-foot-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1280px; margin: 0 auto; }\n.own-airbnb .ab-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-airbnb .ab-foot-col h3 { font-size: 16px; font-weight: 500; margin-bottom: 2px; }\n.own-airbnb .ab-foot-col a { font-size: 14px; color: var(--body); }\n.own-airbnb .ab-foot-col a:hover { text-decoration: underline; }\n.own-airbnb .ab-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1280px; margin: 32px auto 0; padding-top: 20px; border-top: 1px solid var(--hairline-soft); font-size: 13px; color: var(--muted); }\n.own-airbnb .ab-legal-right { display: inline-flex; align-items: center; gap: 16px; }\n.own-airbnb .ab-legal-btn { display: inline-flex; align-items: center; gap: 6px; border: 0; background: transparent; color: var(--muted); font-size: 13px; text-decoration: underline; }\n.own-airbnb .ab-legal-btn svg { width: 15px; height: 15px; }\n.own-airbnb .ab-social { display: inline-grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--ink); color: #fff; font-size: 12px; font-weight: 700; }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-airbnb .ab-tabs { display: none; }\n  .own-airbnb .ab-card-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-airbnb .ab-city-grid { grid-template-columns: repeat(3, 1fr); }\n  .own-airbnb .ab-split { grid-template-columns: 1fr; }\n  .own-airbnb .ab-reserve { position: static; }\n}\n@container frame (max-width: 760px) {\n  .own-airbnb .ab-nav { top: 0; height: auto; padding: 10px 16px; gap: 10px; flex-wrap: wrap; }\n  .own-airbnb .ab-util, .own-airbnb .ab-brand span { display: none; }\n  .own-airbnb .ab-hero { padding: 28px 16px 4px; }\n  .own-airbnb .ab-h1 { font-size: 24px; }\n  .own-airbnb .ab-search { flex-direction: column; align-items: stretch; border-radius: var(--r-lg); padding: 10px; }\n  .own-airbnb .ab-seg { border-radius: var(--r-sm); padding: 8px 14px; }\n  .own-airbnb .ab-seg-div { width: 100%; height: 1px; }\n  .own-airbnb .ab-orb { width: 100%; border-radius: var(--r-sm); height: 44px; }\n  .own-airbnb .ab-band, .own-airbnb .ab-split { padding: 40px 16px 0; }\n  .own-airbnb .ab-city-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-airbnb .ab-card-grid { grid-template-columns: 1fr; }\n  .own-airbnb .ab-reviews { grid-template-columns: 1fr; }\n  .own-airbnb .ab-cta { margin: 40px 16px 0; padding: 28px 20px; }\n  .own-airbnb .ab-footer { padding: 40px 16px 24px; }\n  .own-airbnb .ab-foot-cols { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-airbnb .ab-search { border-radius: var(--r-md); }\n  .own-airbnb .ab-card-grid { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-airbnb *, .own-airbnb *::before, .own-airbnb *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Airbnb-language board cards for showcase.html ═════════════
   Registers window.OWN_LAYOUTS['airbnb'].init(root). Renders the board-card grid,
   wires the wishlist hearts, and returns a cleanup that removes every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var BOARDS = [
    { title: 'Line yield, Luzon', meta: 'Assembly · 6 lines', price: '$12.4M', unit: 'throughput', rating: '4.92', fav: true, ph: 'linear-gradient(135deg,#ffd1da,#ff385c 70%)' },
    { title: 'Port throughput, Busan', meta: 'Port ops · 3 berths', price: '98.1%', unit: 'on-time', rating: '4.88', fav: false, ph: 'linear-gradient(135deg,#cfe3ff,#1e5bff 75%)' },
    { title: 'Fulfilment, Sydney', meta: 'Fulfilment · 2 hubs', price: '$8.9M', unit: 'cost saved', rating: '4.75', fav: true, ph: 'linear-gradient(135deg,#ffe7c2,#ff8a3d 72%)' },
    { title: 'Agri ops, Mindanao', meta: 'Agri ops · 9 sites', price: '94.6%', unit: 'yield', rating: '4.81', fav: false, ph: 'linear-gradient(135deg,#c8f0d8,#0fa58c 74%)' },
    { title: 'Distribution, Singapore', meta: 'Distribution · 4 DCs', price: '$21.2M', unit: 'throughput', rating: '4.90', fav: false, ph: 'linear-gradient(135deg,#e6d8ff,#7b2cf0 74%)' },
    { title: 'Sourcing, Jakarta', meta: 'Sourcing · 11 vendors', price: '91.3%', unit: 'on-time', rating: '4.69', fav: true, ph: 'linear-gradient(135deg,#ffe0e0,#e22718 74%)' },
    { title: 'Recycling, Rotterdam', meta: 'Recycling · 5 lines', price: '$6.1M', unit: 'recovered', rating: '4.84', fav: false, ph: 'linear-gradient(135deg,#d6f5f0,#2dbdb6 74%)' },
    { title: 'Trade desk, Dubai', meta: 'Trade desk · 7 desks', price: '99.2%', unit: 'settled', rating: '4.95', fav: true, ph: 'linear-gradient(135deg,#fff2bf,#f0b90b 74%)' }
  ];

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }

  var HEART = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20s-7-4.4-7-9.2A3.8 3.8 0 0 1 12 8a3.8 3.8 0 0 1 7 2.8C19 15.6 12 20 12 20Z"/></svg>';
  var STAR = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.6l2.9 6 6.6.8-4.9 4.6 1.3 6.5L12 17.3 6.1 20.5l1.3-6.5L2.5 9.4l6.6-.8z"/></svg>';

  OWN['airbnb'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }
      function $(s) { return root.querySelector(s); }

      var grid = $('#abCardGrid');
      if (grid) {
        grid.innerHTML = BOARDS.map(function (b) {
          return '<article class="ab-card">'
            + '<a class="ab-card-photo" href="#" style="--ph:' + b.ph + '" aria-label="' + esc(b.title) + '">'
            + (b.fav ? '<span class="ab-fav">Guest favourite</span>' : '')
            + '<button class="ab-heart' + (b.fav ? ' on' : '') + '" type="button" aria-label="Save board" aria-pressed="' + b.fav + '">' + HEART + '</button>'
            + '</a>'
            + '<a class="ab-card-title" href="#">' + esc(b.title) + '</a>'
            + '<span class="ab-card-meta">' + esc(b.meta) + '</span>'
            + '<div class="ab-card-foot"><span class="ab-card-price">' + esc(b.price) + ' <small>' + esc(b.unit) + '</small></span>'
            + '<span class="ab-card-rating">' + STAR + esc(b.rating) + '</span></div>'
            + '</article>';
        }).join('');
      }

      on(grid, 'click', function (e) {
        var h = e.target.closest('.ab-heart');
        if (!h) return;
        e.preventDefault();
        var on = h.classList.toggle('on');
        h.setAttribute('aria-pressed', String(on));
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
